(()=>{'use strict';
const C=window.WORLD_R3_CONTENT,S=window.WORLD_R3_SOURCES,G=window.WORLD_R3_GEOMETRY,app=document.querySelector('#app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,privateConsent=false,privateData={work:'',constraints:'',question:''},privateShown=false;
const t=v=>v[state.lang==='en'?1:0],pair=(zh,en)=>t([zh,en]);
const question=id=>C.groups.flatMap(g=>g.questions).find(q=>q[0]===id);
function restore(){const p=new URLSearchParams(location.search);state={lang:p.get('lang')==='en'?'en':'zh-Hans',view:['answer','gap'].includes(p.get('view'))?p.get('view'):'home',id:p.get('id')||'cost',region:['MYS','VNM','GLOBAL'].includes(p.get('region'))?p.get('region'):'MYS',year:['2023','2024','2025'].includes(p.get('year'))?p.get('year'):'2024',scale:['now','history','compare'].includes(p.get('scale'))?p.get('scale'):(p.get('id')==='compare'?'compare':'now'),q:(p.get('q')||'').slice(0,500)};if(state.view==='answer'&&!C.answers[state.id])state.view='gap';}
function url(patch={}){const next={...state,...patch},u=new URL(location.href);u.search='';u.hash='';for(const k of ['lang','view','id','region','year','scale','q'])if(next[k])u.searchParams.set(k,next[k]);return u;}
function clearPrivate(){privateConsent=false;privateShown=false;privateData={work:'',constraints:'',question:''};}
function go(patch,{focus=true}={}){const changed=['region','year','id'].some(k=>patch[k]&&patch[k]!==state[k]);if(changed)clearPrivate();history.pushState(null,'',url(patch));restore();render();if(focus){window.scrollTo(0,0);document.querySelector('h1')?.focus();}}
function route(id,q){go({id,view:C.answers[id]?'answer':'gap',q:q||t(question(id)?.slice(1)||['','']),scale:id==='compare'?'compare':state.scale});}
const country=()=>state.id==='compare'&&state.view==='answer'?pair('马来西亚 × 越南','Malaysia × Vietnam'):({MYS:pair('马来西亚','Malaysia'),VNM:pair('越南','Vietnam'),GLOBAL:pair('全球范围','World scope')})[state.region];
function header(){return `<a class="skip" href="#main">${pair('跳到内容','Skip to content')}</a><header class="top"><div class="wrap"><a class="brand" href="${esc(url({view:'home'}))}" data-home>PHI OS <span>${pair('世界','World')}</span></a><div class="language" aria-label="${pair('语言','Language')}"><button data-lang="zh-Hans" aria-pressed="${state.lang==='zh-Hans'}">中文</button><button data-lang="en" aria-pressed="${state.lang==='en'}">EN</button></div></div></header><div class="wrap"><p class="prototype-note">${pair('WORLD R3 · 设计审阅原型 · 不联网生成，不写入账户','WORLD R3 · Design review prototype · No generated answers or account writes')}</p></div>`;}
function footer(){return `<footer class="wrap page-footer"><span>${pair('公共事实、解释与个人条件，分别保留来源。','Keep the provenance of public facts, interpretations and personal circumstances distinct.')}</span><a href="../WORLD-R3-HUMAN-REVIEW.html">${pair('返回人审入口','Back to Human Review')}</a></footer>`;}
function scales(){return `<div class="scales" role="tablist" aria-label="${pair('阅读尺度','Reading scale')}">${[['now','世界现况','World now'],['history','结构与历史','Structure & history'],['compare','比较与变化','Compare & change']].map(([id,zh,en])=>`<button role="tab" data-scale="${id}" aria-selected="${state.scale===id}" tabindex="${state.scale===id?0:-1}">${pair(zh,en)}</button>`).join('')}</div>`;}
function scaleHelp(){return ({now:pair('先核对有地区与日期的事实；缺少观测时，明确保留空缺。','Start with place- and period-specific facts, retaining gaps where observations are absent.'),history:pair('阅读形成机制与历史背景，不把书稿解释当成当年统计。','Read mechanisms and historical context without treating manuscripts as current statistics.'),compare:pair('先对齐年份、定义与单位，再讨论差异；不生成地区总分。','Align year, definition and unit before discussing differences. No overall place score is produced.')})[state.scale];}
function search(){return `<form class="search" data-search><label class="sr-only" for="question-search">${pair('搜索国家、地点、主题或公共问题','Search a country, place, topic or public question')}</label><input id="question-search" name="q" maxlength="500" autocomplete="off" value="${esc(state.view==='home'?state.q:'')}" placeholder="${pair('国家、地点、主题，或一个现实问题','A place, topic, or real-life question')}" required><button class="solid" type="submit">${pair('探索','Explore')}</button></form>`;}
function home(){return `<main id="main" class="wrap"><section class="hero"><p class="eyebrow">${pair('从问题开始，理解世界','Start with a question. Understand the world.')}</p><h1 tabindex="-1">${pair('世界正在怎样变化，<br>又怎样进入我们的生活？','How is the world changing,<br>and how does it reach our lives?')}</h1><p class="lede">${pair('从你关心的事出发，找到证据、理解联系，再决定下一步要问什么。','Start with what matters to you. Find evidence, understand connections, and decide what to investigate next.')}</p>${search()}<p class="minor">${pair('这里只输入公共问题。个人条件可在“世界与我”中另行选择加入。','Enter public questions here. Personal circumstances can be added separately in “The world & me”.')}</p></section><section aria-label="${pair('六组现实问题','Six groups of real-life questions')}"><div class="six">${C.groups.map((g,i)=>`<article class="question-group"><span class="group-no" aria-hidden="true">0${i+1}</span><p class="group-name">${esc(t(g.name))}</p>${g.questions.map(([id,zh,en],j)=>`<a class="${j?'more-question':''}" href="${esc(url({view:C.answers[id]?'answer':'gap',id,q:pair(zh,en),scale:id==='compare'?'compare':state.scale}))}" data-question="${id}">${esc(pair(zh,en))}${j?' ↗':''}</a>`).join('')}</article>`).join('')}</div></section>${scales()}<p class="scale-help" role="tabpanel">${scaleHelp()}</p><div class="home-bottom"><p>${pair('书籍与图谱会在有助于解释问题时出现；不需要先选书，也不需要先填写个人资料。','Books and atlases enter when they help explain the question. You do not need to choose a volume or enter personal information first.')}</p><a href="https://getphios.com/world/" target="_blank" rel="noopener">${pair('打开现有 World R2 ↗','Open existing World R2 ↗')}</a></div><p class="minor">${pair('本次设计提供三种完整示例：生活成本、跨地区比较、世界与我。其他问题保留覆盖缺口，不替换成无关答案。','This design contains three complete examples: living costs, cross-region comparison, and the world & me. Other questions retain their coverage gaps rather than receiving unrelated answers.')}</p></main>`;}
function sourceLink(id,label){const s=S[id];return `<a href="${esc(s.href[state.lang]||s.href.all)}" target="_blank" rel="noopener">${esc(label||t(s.label))} ↗</a>`;}
function sourceMeta(id){const s=S[id];return s.kind==='official'?pair('官方定义网页 · 2026-10-20核对 · 未载入年度值','Official definition page · checked 2026-10-20 · no annual values loaded'):pair('既有已发布正文 · v','Existing published reading · v')+s.locales[state.lang].version+pair(' · 不是当前统计',' · not a current statistic');}
function scopedControls(){return `<div class="scope"><label>${pair('观察范围','Scope')} ${['cost','compare'].includes(state.id)?'<strong>'+(state.id==='cost'?pair('马来西亚（示例范围）','Malaysia (example scope)'):country())+'</strong>':`<select data-region>${[['MYS','马来西亚','Malaysia'],['VNM','越南','Vietnam'],['GLOBAL','全球','World']].map(([v,zh,en])=>`<option value="${v}" ${state.region===v?'selected':''}>${pair(zh,en)}</option>`).join('')}</select>`}</label><label>${pair('观察年份','Observation year')} <select data-year>${['2023','2024','2025'].map(y=>`<option ${y===state.year?'selected':''}>${y}</option>`).join('')}</select></label><span class="badge gap">${pair('年度值未载入','Annual observations not loaded')}</span></div>`;}
function diagram(a){if(state.id==='compare')return `<div class="map"><svg viewBox="810 175 130 110" role="img" aria-labelledby="map-title map-desc"><title id="map-title">${pair('马来西亚与越南的相对位置','Relative locations of Malaysia and Vietnam')}</title><desc id="map-desc">${esc(t(a.visualNote))}</desc>${G.map(f=>`<path class="land ${['MYS','VNM'].includes(f.id)?f.id:''}" d="${esc(f.d)}"><title>${esc(f.name[state.lang==='en'?'en':'zh'])}</title></path>`).join('')}</svg><div class="map-legend"><span>${pair('马来西亚','Malaysia')}</span><span>${pair('越南','Vietnam')}</span></div></div>`;return `<div class="flow" role="group" aria-label="${esc(t(a.visualTitle))}">${a.flow.map(n=>`<div class="flow-cell"><strong>${esc(t(n[0]))}</strong><small>${esc(t(n[1]))}</small></div>`).join('')}</div>`;}
function comparison(){return `<table class="comparison"><caption class="sr-only">${pair('待核对的产业比较，不含观测值','Sector comparison to verify, without observed values')}</caption><thead><tr><th>${pair('比较维度','Dimension')}</th><th>${pair('马来西亚','Malaysia')}</th><th>${pair('越南','Vietnam')}</th></tr></thead><tbody>${[['产业增加值','Sector value added'],['产业就业','Sector employment'],['出口构成','Export composition']].map(([zh,en])=>`<tr><th scope="row">${pair(zh,en)}</th><td><span class="pending">${pair('待接入同年资料','Same-year evidence needed')}</span></td><td><span class="pending">${pair('待接入同年资料','Same-year evidence needed')}</span></td></tr>`).join('')}</tbody></table><p class="minor">${pair('需要逐行核对部门分类、分母、单位与修订版本；不能将“工业占GDP”与“制造业就业”互相比高低。','Sector classification, denominator, unit and revision must be checked row by row. Industry’s share of GDP cannot be ranked against manufacturing employment.')}</p>`;}
function privatePanel(){return `<section id="your-context"><h2>${pair('由你决定，是否加入自己的条件','You decide whether to add your circumstances')}</h2><div class="private-box"><label><input type="checkbox" data-private-consent ${privateConsent?'checked':''}>${pair('我选择只在本页整理自己的自述资料。','I choose to organize my self-reported circumstances on this page only.')}</label><p class="minor">${pair('不保存、不上传、不写入链接；刷新或关闭会清除。你可以不填，继续阅读。','Nothing is saved, uploaded, or put in the link. Refreshing or closing clears it. You can continue without entering anything.')}</p>${privateConsent?`${[['work','我的工作或当前安排','My work or current arrangements'],['constraints','必须承担的责任与现实限制','Responsibilities and real constraints'],['question','我还需要核实什么','What I still need to verify']].map(([k,zh,en])=>`<label>${pair(zh,en)}<textarea maxlength="1500" data-private="${k}">${esc(privateData[k])}</textarea></label>`).join('')}<div class="private-actions"><button type="button" class="solid" data-organize>${pair('分开查看我的自述与公共解释','Review my statements separately')}</button><button type="button" class="outline" data-clear-private>${pair('清除自述资料','Clear my statements')}</button></div>${privateShown?`<div class="private-output"><strong>${pair('仅为本人自述，尚未独立核实','Self-reported only; not independently verified')}</strong>${['work','constraints','question'].map(k=>privateData[k]?'<p>'+esc(privateData[k])+'</p>':'').join('')}<p>${pair('这些输入没有改变上方公共事实，也没有生成个人结论。','These statements have not changed the public evidence above or produced a personal conclusion.')}</p></div>`:''}`:''}</div><details><summary>${pair('已有 PHI Configuration 或 Profile？','Already have PHI Configuration or Profile material?')}</summary><p class="minor">${pair('可以另开原入口查看。个人方法解释保留原来源身份，不自动导入公共问题，不成为世界事实。','Open the existing entry separately. Method interpretations keep their original provenance; they are not automatically imported or treated as world facts.')}</p><div class="follow"><a href="https://getphios.com/perspectives/phi-configuration/" target="_blank" rel="noopener">PHI Configuration ↗</a><a href="https://getphios.com/perspectives/profile/" target="_blank" rel="noopener">Profile ↗</a></div></details></section>`;}
function answer(){const a=C.answers[state.id],defaultQuestion=t(a.title);return `<main id="main" class="wrap"><a class="back" href="${esc(url({view:'home'}))}" data-home>← ${pair('回到问题入口','Back to questions')}</a><header class="answer-head"><p class="eyebrow">${esc(t(a.type))}</p><h1 tabindex="-1">${esc(defaultQuestion)}</h1>${state.q&&state.q!==defaultQuestion?`<p class="minor" data-original-question>${pair('原始问题（保留输入语言）：','Original question (language retained): ')}${esc(state.q)}</p>`:''}${scopedControls()}<span class="badge">${esc(t(a.tag))}</span><p class="minor">${pair('年份是你选择的范围，不是“最新数据已更新”的声明。','The year is your selected scope, not a claim that the latest data have been loaded.')}</p></header><div class="answer-layout"><article class="answer-main"><section class="direct" id="answer"><h2>${pair('直接回答','THE SHORT ANSWER')}</h2><p class="answer-copy">${esc(t(a.short))}</p><p class="minor">${esc(t(a.boundary))}</p></section><div class="answer-perspectives">${scales()}<p class="mode-note" role="tabpanel">${scaleHelp()}</p></div><section id="evidence"><h2>${pair('已有依据与证据缺口','What supports this—and what is missing')}</h2>${a.evidence.map(e=>`<div class="evidence-item"><span class="badge">${pair(S[e.source].kind==='official'?'事实 · 指标定义':'解释来源 · 不是地区观测',S[e.source].kind==='official'?'Fact · indicator definition':'Interpretive source · not a regional observation')}</span><h3 style="margin-top:12px">${esc(t(e.label))}</h3><p>${esc(t(e.text))}</p>${sourceLink(e.source)}<div class="meta">${sourceMeta(e.source)}</div>${S[e.source].kind==='reading'?`<details><summary>${pair('核对原文段落与相关图示','Inspect original passages and related visuals')}</summary>${S[e.source].locales[state.lang].passages.map(p=>`<p>${esc(p.text)}</p><small>${esc(p.pointer)} · ${esc(p.anchor)}</small>`).join('')}${S[e.source].locales[state.lang].atlasLinks.concat(S[e.source].locales[state.lang].figures).map(x=>`<p><a target="_blank" rel="noopener" href="https://getphios.com${esc(x.href)}">${esc(x.label)} ↗</a></p>`).join('')}</details>`:''}</div>`).join('')}<div class="gaps"><strong>${pair('当前还不能断言','Not yet established')}</strong><p>${esc(t(a.gaps))}</p></div>${state.id==='compare'?comparison():''}</section><section id="mechanism"><span class="badge">${pair('解释，不是年度因果估计','Interpretation, not an annual causal estimate')}</span><h2 style="margin-top:12px">${pair('为什么可能这样发生','How the connection can work')}</h2>${a.mechanism.map((m,i)=>`<div class="mechanism-step"><span class="step-no" aria-hidden="true">0${i+1}</span><div><h3>${esc(t(m[0]))}</h3><p>${esc(t(m[1]))}</p></div></div>`).join('')}<p class="minor">${pair('解释依据：','Interpretive basis: ')}${a.readings.map(id=>sourceLink(id,t(S[id].label))).join(' · ')}</p></section><section id="visual"><h2>${esc(t(a.visualTitle))}</h2>${diagram(a)}<p class="flow-subtitle">${esc(t(a.visualNote))}</p></section><section id="impacts"><h2>${pair('与日常生活有什么关系','What this could mean in daily life')}</h2><div class="impact-grid">${a.impacts.map(m=>`<div><h3>${esc(t(m[0]))}</h3><p>${esc(t(m[1]))}</p></div>`).join('')}</div></section>${state.id==='personal'?privatePanel():''}<section id="limits"><h2>${pair('未知、争议与不可推断','Unknowns, disagreement and limits')}</h2><p>${esc(t(a.limits))}</p><p class="minor">${pair('本页没有使用模型补齐缺口，也没有执行购买、账户保存、资料分享或行动。','No model has filled these gaps. No purchase, account save, sharing or action has been executed.')}</p></section><section id="next"><h2>${pair('继续阅读与追问','Read further. Ask a better next question.')}</h2>${a.readings.map(id=>`<a class="source-link" href="${esc(S[id].href[state.lang])}" target="_blank" rel="noopener"><strong>${esc(t(S[id].label))} ↗</strong><small>${esc(S[id].book)} · ${sourceMeta(id)}<br>${esc(t(a.readingNotes[id]))} · ${pair('外开已有正文','opens the existing reading')}</small></a>`).join('')}<div class="follow">${a.follow.map(([id,zh,en])=>`<a href="${esc(url({id,view:'answer',q:t(C.answers[id].title)}))}" data-question="${id}">${esc(pair(zh,en))} →</a>`).join('')}</div><details><summary>${pair('继续到已有 Ask 入口前','Before continuing to the existing Ask entry')}</summary><p class="minor">${pair('原型不会自动提交问题。Gate 1 发现现有 R2 入口仍缺部分地区／时间上下文；进入正式 Ask 后须重新核对来源、许可与范围。','The prototype does not submit a question. Gate 1 found gaps in R2’s place/time handoff. Review sources, permissions and scope inside the existing Ask product before submitting.')}</p><a href="https://getphios.com/knowledge/ask/" target="_blank" rel="noopener">${pair('另开已有 Ask ↗','Open existing Ask separately ↗')}</a></details></section></article><aside class="side" aria-label="${pair('本页内容','On this page')}"><details data-toc><summary>${pair('本页导航','On this page')}</summary><nav>${[['answer','直接回答','Short answer'],['evidence','依据与缺口','Evidence & gaps'],['mechanism','形成机制','Mechanism'],['visual','图示与位置','Visual & location'],['limits','限制','Limits'],['next','继续阅读','Read further']].map(([id,zh,en])=>`<a href="#${id}">${pair(zh,en)}</a>`).join('')}</nav><p>${pair('解释与统计分开；<br>缺失不当作零。','Keep explanations and statistics separate.<br>Missing does not mean zero.')}</p></details></aside></div></main>`;}
function gap(){return `<main id="main" class="wrap"><a class="back" href="${esc(url({view:'home'}))}" data-home>← ${pair('回到问题入口','Back to questions')}</a><article class="uncovered"><p class="eyebrow">${pair('检索范围与缺口','Retrieval scope & gaps')}</p><h1 tabindex="-1">${esc(state.q||t(question(state.id)?.slice(1)||['这个公共问题','This public question']))}</h1>${scopedControls()}<span class="badge gap">${pair('尚无已核对的完整答案','No verified complete answer yet')}</span><p style="margin-top:22px">${pair('这条问题不属于本次三个完整示例。它会保留为原问题，不换成其他答案，也不自动推荐无关文章。','This question is outside the three complete examples. The original question is retained; it is not replaced by another answer or unrelated fixed recommendations.')}</p><div class="gaps">${pair('需要匹配地区、时期与问题定义的证据。R2 现有的人口和现价 GDP 不足以回答这些专题问题。','Evidence must match the place, period and question. R2’s population and current-dollar GDP alone cannot answer these topic-specific questions.')}</div><div class="follow"><a href="https://getphios.com/search/?q=${encodeURIComponent(state.q)}" target="_blank" rel="noopener">${pair('去已有内容目录继续找线索 ↗','Explore the existing content catalogue ↗')}</a><a href="${esc(url({view:'home'}))}" data-home>${pair('重新选择问题','Choose another question')}</a></div>${search()}</article></main>`;}
function render(){document.documentElement.lang=state.lang;document.title=pair('World R3 · 问题引导设计','World R3 · Question-led design');app.innerHTML=header()+(state.view==='home'?home():state.view==='answer'?answer():gap())+footer();bind();}
function bind(){const toc=app.querySelector('[data-toc]');if(toc)toc.open=innerWidth>900;app.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>go({lang:b.dataset.lang},{focus:false}));app.querySelectorAll('[data-home]').forEach(a=>a.onclick=e=>{e.preventDefault();go({view:'home'});});app.querySelectorAll('[data-question]').forEach(a=>a.onclick=e=>{e.preventDefault();route(a.dataset.question);});app.querySelectorAll('[data-scale]').forEach(b=>{b.onclick=()=>go({scale:b.dataset.scale},{focus:false});b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const ids=['now','history','compare'],i=ids.indexOf(state.scale),next=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;go({scale:ids[next]},{focus:false});app.querySelector('[data-scale="'+ids[next]+'"]').focus();};});app.querySelector('[data-region]')?.addEventListener('change',e=>go({region:e.target.value},{focus:false}));app.querySelector('[data-year]')?.addEventListener('change',e=>go({year:e.target.value},{focus:false}));app.querySelectorAll('[data-search]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const q=new FormData(form).get('q').trim();if(!q)return;const normalized=q.normalize('NFKC').toLowerCase().replace(/[?？。，,.!！\s]/g,'');const match=C.groups.flatMap(g=>g.questions).find(r=>r.slice(1).some(s=>s.normalize('NFKC').toLowerCase().replace(/[?？。，,.!！\s]/g,'')===normalized));const curatedAliases={'为什么经济增长不代表每个家庭更富裕':'cost','为什么拥有丰富自然资源的国家不一定富裕':'resources','石油价格为什么影响普通家庭':'oil'};const alias=curatedAliases[normalized];if(match||alias){route(match?match[0]:alias,q);return;}const place={malaysia:'MYS','马来西亚':'MYS',vietnam:'VNM','越南':'VNM'}[q.toLowerCase()];go({q,id:'unmatched',view:'gap',...(place?{region:place}:{})});});app.querySelector('[data-private-consent]')?.addEventListener('change',e=>{if(!e.target.checked)clearPrivate();else privateConsent=true;render();});app.querySelectorAll('[data-private]').forEach(e=>e.oninput=()=>{privateData[e.dataset.private]=e.value;privateShown=false;});app.querySelector('[data-organize]')?.addEventListener('click',()=>{privateShown=true;render();document.querySelector('.private-output')?.scrollIntoView({block:'center'});});app.querySelector('[data-clear-private]')?.addEventListener('click',()=>{clearPrivate();render();});}
window.addEventListener('popstate',()=>{clearPrivate();restore();render();});window.addEventListener('pagehide',clearPrivate);restore();render();
window.__worldR3Design=Object.freeze({publicState:()=>({...state}),kind:'GATE2_DESIGN_NOT_PRODUCT_IMPLEMENTATION'});
})();
